static
void kernel_atax(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

#pragma scop
  // Initialize y to 0
  for (i = 0; i < _PB_N; i++)
    y[i] = 0;

  for (i = 0; i < _PB_M; i++)
    {
      // Compute tmp[i] = sum(A[i][j] * x[j])
      #if defined(__riscv_vector)
      size_t vl;
      vfloat64m1_t v_tmp = __riscv_vfmv_v_f_f64m1(0.0, 1);
      size_t n_vec = n;
      size_t j_vec = 0;

      // Vectorized dot product for tmp[i]
      while (j_vec + __riscv_vsetvl_e64m1(n_vec - j_vec) <= n_vec) {
        vfloat64m1_t v_a = __riscv_vle64_v_f64m1(&A[i][j_vec], __riscv_vsetvl_e64m1(n_vec - j_vec));
        vfloat64m1_t v_x = __riscv_vle64_v_f64m1(&x[j_vec], __riscv_vsetvl_e64m1(n_vec - j_vec));
        vfloat64m1_t v_prod = __riscv_vfmul_vv_f64m1(v_a, v_x, __riscv_vsetvl_e64m1(n_vec - j_vec));
        v_tmp = __riscv_vfadd_vv_f64m1(v_tmp, v_prod, __riscv_vsetvl_e64m1(n_vec - j_vec));
        j_vec += __riscv_vsetvl_e64m1(n_vec - j_vec);
      }

      // Handle remaining elements
      for (; j_vec < n; j_vec++) {
        v_tmp = __riscv_vfadd_vf_f64m1(v_tmp, A[i][j_vec] * x[j_vec], 1);
      }

      tmp[i] = __riscv_vfmv_s_f_f64m1(v_tmp);
      #else
      tmp[i] = SCALAR_VAL(0.0);
      for (j = 0; j < _PB_N; j++)
        tmp[i] = tmp[i] + A[i][j] * x[j];
      #endif

      // Update y[j] += A[i][j] * tmp[i]
      #if defined(__riscv_vector)
      j_vec = 0;

      while (j_vec + __riscv_vsetvl_e64m1(n_vec - j_vec) <= n_vec) {
        vfloat64m1_t v_a = __riscv_vle64_v_f64m1(&A[i][j_vec], __riscv_vsetvl_e64m1(n_vec - j_vec));
        vfloat64m1_t v_y = __riscv_vle64_v_f64m1(&y[j_vec], __riscv_vsetvl_e64m1(n_vec - j_vec));
        vfloat64m1_t v_prod = __riscv_vfmul_vf_f64m1(v_a, tmp[i], __riscv_vsetvl_e64m1(n_vec - j_vec));
        vfloat64m1_t v_y_new = __riscv_vfadd_vv_f64m1(v_y, v_prod, __riscv_vsetvl_e64m1(n_vec - j_vec));
        __riscv_vse64_v_f64m1(&y[j_vec], v_y_new, __riscv_vsetvl_e64m1(n_vec - j_vec));
        j_vec += __riscv_vsetvl_e64m1(n_vec - j_vec);
      }

      // Handle remaining elements
      for (; j_vec < n; j_vec++) {
        y[j_vec] = y[j_vec] + A[i][j_vec] * tmp[i];
      }
      #else
      for (j = 0; j < _PB_N; j++)
        y[j] = y[j] + A[i][j] * tmp[i];
      #endif
    }
#pragma endscop

}

