static
void kernel_bicg(int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		 DATA_TYPE POLYBENCH_1D(s,M,m),
		 DATA_TYPE POLYBENCH_1D(q,N,n),
		 DATA_TYPE POLYBENCH_1D(p,M,m),
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

#pragma scop
  // Initialize s array to 0
  for (i = 0; i < _PB_M; i++)
    s[i] = 0;

  // Main computation loop
  for (i = 0; i < _PB_N; i++)
    {
      q[i] = SCALAR_VAL(0.0);
      DATA_TYPE r_val = r[i];

      // Use scalar loop for now as the inner loop has dependencies across iterations
      // that make vectorization complex without loop transformation
      for (j = 0; j < _PB_M; j++)
	{
	  s[j] = s[j] + r_val * A[i][j];
	  q[i] = q[i] + A[i][j] * p[j];
	}
    }
#pragma endscop

}

