static
void kernel_durbin(int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
 DATA_TYPE z[N];
 DATA_TYPE alpha;
 DATA_TYPE beta;
 DATA_TYPE sum;

 int i,k;

#pragma scop
 y[0] = -r[0];
 beta = SCALAR_VAL(1.0);
 alpha = -r[0];

 for (k = 1; k < _PB_N; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = SCALAR_VAL(0.0);

   // Inner loop 1: sum += r[k-i-1]*y[i]
   for (i=0; i<k; i++) {
      sum += r[k-i-1]*y[i];
   }
   alpha = - (r[k] + sum)/beta;

   // Inner loop 2: z[i] = y[i] + alpha*y[k-i-1]
   for (i=0; i<k; i++) {
      z[i] = y[i] + alpha*y[k-i-1];
   }

   // Inner loop 3: y[i] = z[i]
   #if defined(__riscv_vector)
   {
     size_t len = k;
     size_t idx = 0;

     while (idx < len) {
       size_t vlen = __riscv_vsetvl_e64m1(len - idx);
       vfloat64m1_t vz = __riscv_vle64_v_f64m1(&z[idx], vlen);
       __riscv_vse64_v_f64m1(&y[idx], vz, vlen);
       idx += vlen;
     }
   }
   #else
   for (i=0; i<k; i++) {
     y[i] = z[i];
   }
   #endif

   y[k] = alpha;
 }
#pragma endscop

}

