static
void kernel_fdtd_2d(int tmax,
		    int nx,
		    int ny,
		    DATA_TYPE POLYBENCH_2D(ex,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(ey,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_2D(hz,NX,NY,nx,ny),
		    DATA_TYPE POLYBENCH_1D(_fict_,TMAX,tmax))
{
  int t, i, j;

#pragma scop

  for(t = 0; t < _PB_TMAX; t++)
    {
      // Update ey[0][j] = _fict_[t]
      for (j = 0; j < _PB_NY; j++)
	ey[0][j] = _fict_[t];

      // Update ey[i][j] for i=1..NX-1
      for (i = 1; i < _PB_NX; i++)
	{
#if defined(__riscv_vector)
	  size_t vl;
	  vfloat32m1_t v_ey, v_hz_curr, v_hz_prev;
	  vfloat32m1_t v_const = __riscv_vfmv_v_f(SCALAR_VAL(0.5), 0);
	  size_t j_vec = 0;
	  size_t n_vec = _PB_NY;

	  // Vectorized inner loop for ey update
	  for (j_vec = 0; j_vec < n_vec; j_vec += vl)
	    {
	      vl = __riscv_vsetvl_e32m1(n_vec - j_vec);
	      v_ey = __riscv_vle32_vf(ey[i], vl);
	      v_hz_curr = __riscv_vle32_vf(hz[i], vl);
	      v_hz_prev = __riscv_vle32_vf(hz[i-1], vl);

	      v_hz_curr = __riscv_vsub_vf(v_hz_curr, v_hz_prev, vl);
	      v_hz_curr = __riscv_vfmul_vf(v_hz_curr, v_const, vl);
	      v_ey = __riscv_vsub_vf(v_ey, v_hz_curr, vl);

	      __riscv_vse32_vf(ey[i], v_ey, vl);
	    }
#else
	  for (j = 0; j < _PB_NY; j++)
	    ey[i][j] = ey[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i-1][j]);
#endif
	}

      // Update ex[i][j] for j=1..NY-1
      for (i = 0; i < _PB_NX; i++)
	{
#if defined(__riscv_vector)
	  size_t vl;
	  vfloat32m1_t v_ex, v_hz_curr, v_hz_prev;
	  vfloat32m1_t v_const = __riscv_vfmv_v_f(SCALAR_VAL(0.5), 0);
	  size_t j_vec = 1;
	  size_t n_vec = _PB_NY - 1;

	  // Vectorized inner loop for ex update (starting from j=1)
	  for (j_vec = 1; j_vec < _PB_NY; j_vec += vl)
	    {
	      vl = __riscv_vsetvl_e32m1(_PB_NY - j_vec);
	      v_ex = __riscv_vle32_vf(&ex[i][j_vec], vl);
	      v_hz_curr = __riscv_vle32_vf(&hz[i][j_vec], vl);
	      v_hz_prev = __riscv_vle32_vf(&hz[i][j_vec-1], vl);

	      v_hz_curr = __riscv_vsub_vf(v_hz_curr, v_hz_prev, vl);
	      v_hz_curr = __riscv_vfmul_vf(v_hz_curr, v_const, vl);
	      v_ex = __riscv_vsub_vf(v_ex, v_hz_curr, vl);

	      __riscv_vse32_vf(&ex[i][j_vec], v_ex, vl);
	    }
#else
	  for (j = 1; j < _PB_NY; j++)
	    ex[i][j] = ex[i][j] - SCALAR_VAL(0.5)*(hz[i][j]-hz[i][j-1]);
#endif
	}

      // Update hz[i][j] for i=0..NX-2, j=0..NY-2
      for (i = 0; i < _PB_NX - 1; i++)
	{
#if defined(__riscv_vector)
	  size_t vl;
	  vfloat32m1_t v_hz, v_ex_curr, v_ex_prev, v_ey_curr, v_ey_prev;
	  vfloat32m1_t v_const = __riscv_vfmv_v_f(SCALAR_VAL(0.7), 0);
	  size_t j_vec = 0;
	  size_t n_vec = _PB_NY - 1;

	  // Vectorized inner loop for hz update
	  for (j_vec = 0; j_vec < n_vec; j_vec += vl)
	    {
	      vl = __riscv_vsetvl_e32m1(n_vec - j_vec);
	      v_hz = __riscv_vle32_vf(&hz[i][j_vec], vl);
	      v_ex_curr = __riscv_vle32_vf(&ex[i][j_vec+1], vl);
	      v_ex_prev = __riscv_vle32_vf(&ex[i][j_vec], vl);
	      v_ey_curr = __riscv_vle32_vf(&ey[i+1][j_vec], vl);
	      v_ey_prev = __riscv_vle32_vf(&ey[i][j_vec], vl);

	      v_ex_curr = __riscv_vsub_vf(v_ex_curr, v_ex_prev, vl);
	      v_ey_curr = __riscv_vsub_vf(v_ey_curr, v_ey_prev, vl);
	      v_ex_curr = __riscv_vadd_vf(v_ex_curr, v_ey_curr, vl);
	      v_ex_curr = __riscv_vfmul_vf(v_ex_curr, v_const, vl);
	      v_hz = __riscv_vsub_vf(v_hz, v_ex_curr, vl);

	      __riscv_vse32_vf(&hz[i][j_vec], v_hz, vl);
	    }
#else
	  for (j = 0; j < _PB_NY - 1; j++)
	    hz[i][j] = hz[i][j] - SCALAR_VAL(0.7)*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
#endif
	}
    }

#pragma endscop
}

