static
void kernel_floyd_warshall(int n,
			   DATA_TYPE POLYBENCH_2D(path,N,N,n,n))
{
  int i, j, k;

#pragma scop
  for (k = 0; k < _PB_N; k++)
    {
      for(i = 0; i < _PB_N; i++)
	{
#if defined(__riscv_vector)
	  size_t j_vec = 0;
	  size_t n_vec = _PB_N;
	  size_t vlen = __riscv_vsetvl_e32m1(n_vec);

	  // Process vectorized portion
	  while (j_vec + vlen <= n_vec) {
	    vint32m1_t v_path_ik = __riscv_vmv_v_x_i32m1(path[i][k], vlen);
	    vint32m1_t v_path_kj = __riscv_vle32_v_i32m1(&path[k][j_vec], vlen);
	    vint32m1_t v_sum = __riscv_vadd_vv_i32m1(v_path_ik, v_path_kj, vlen);
	    vint32m1_t v_path_ij = __riscv_vle32_v_i32m1(&path[i][j_vec], vlen);
	    vint32m1_t v_min = __riscv_vmin_vv_i32m1(v_path_ij, v_sum, vlen);
	    __riscv_vse32_v_i32m1(&path[i][j_vec], v_min, vlen);
	    j_vec += vlen;
	  }
#else
	  for (j = 0; j < _PB_N; j++)
#endif
	  {
#if !defined(__riscv_vector)
	    path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
	      path[i][j] : path[i][k] + path[k][j];
#else
	    // Scalar tail
	    for (j = j_vec; j < _PB_N; j++)
	      path[i][j] = path[i][j] < path[i][k] + path[k][j] ?
		path[i][j] : path[i][k] + path[k][j];
#endif
	  }
	}
    }
#pragma endscop

}

