static
void kernel_gemver(int n,
		   DATA_TYPE alpha,
		   DATA_TYPE beta,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(u1,N,n),
		   DATA_TYPE POLYBENCH_1D(v1,N,n),
		   DATA_TYPE POLYBENCH_1D(u2,N,n),
		   DATA_TYPE POLYBENCH_1D(v2,N,n),
		   DATA_TYPE POLYBENCH_1D(w,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n),
		   DATA_TYPE POLYBENCH_1D(z,N,n))
{
  int i, j;

#pragma scop

  // Loop 1: A[i][j] = A[i][j] + u1[i] * v1[j] + u2[i] * v2[j]
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE u1_val = u1[i];
    DATA_TYPE u2_val = u2[i];

#if defined(__riscv_vector)
    size_t vl = __riscv_vsetvl_e32m1(_PB_N);
    vfloat32m1_t u1_vec = __riscv_vfmv_v_f(vl, u1_val);
    vfloat32m1_t u2_vec = __riscv_vfmv_v_f(vl, u2_val);
    vfloat32m1_t v1_vec = __riscv_vle32_v(v1, vl);
    vfloat32m1_t v2_vec = __riscv_vle32_v(v2, vl);
    vfloat32m1_t prod1 = __riscv_vfmul_vv(u1_vec, v1_vec, vl);
    vfloat32m1_t prod2 = __riscv_vfmul_vv(u2_vec, v2_vec, vl);
    vfloat32m1_t sum = __riscv_vfadd_vv(prod1, prod2, vl);
    vfloat32m1_t a_row = __riscv_vle32_v(&A[i][0], vl);
    vfloat32m1_t result = __riscv_vfadd_vv(a_row, sum, vl);
    __riscv_vse32_v(&A[i][0], result, vl);
#else
    for (j = 0; j < _PB_N; j++) {
      A[i][j] = A[i][j] + u1_val * v1[j] + u2_val * v2[j];
    }
#endif
  }

  // Loop 2: x[i] = x[i] + beta * A[j][i] * y[j]
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE x_val = x[i];

#if defined(__riscv_vector)
    size_t vl = __riscv_vsetvl_e32m1(_PB_N);
    vfloat32m1_t y_vec = __riscv_vle32_v(y, vl);

    // Load column i of A (A[j][i] for j=0..N-1)
    // Since A is row-major, we need to load with stride
    vfloat32m1_t a_col = __riscv_vle32_v_stride(&A[0][i], _PB_N, vl);

    vfloat32m1_t prod = __riscv_vfmul_vv(a_col, y_vec, vl);
    prod = __riscv_vfmul_vf(prod, beta, vl);
    vfloat32m1_t sum = __riscv_vfredosum_vs(prod, 0.0, vl);
    x[i] = x_val + sum;
#else
    for (j = 0; j < _PB_N; j++) {
      x_val = x_val + beta * A[j][i] * y[j];
    }
    x[i] = x_val;
#endif
  }

  // Loop 3: x[i] = x[i] + z[i]
#if defined(__riscv_vector)
  {
    size_t vl = __riscv_vsetvl_e32m1(_PB_N);
    vfloat32m1_t x_vec = __riscv_vle32_v(x, vl);
    vfloat32m1_t z_vec = __riscv_vle32_v(z, vl);
    vfloat32m1_t result = __riscv_vfadd_vv(x_vec, z_vec, vl);
    __riscv_vse32_v(x, result, vl);
  }
#else
  for (i = 0; i < _PB_N; i++) {
    x[i] = x[i] + z[i];
  }
#endif

  // Loop 4: w[i] = w[i] + alpha * A[i][j] * x[j]
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE w_val = w[i];

#if defined(__riscv_vector)
    size_t vl = __riscv_vsetvl_e32m1(_PB_N);
    vfloat32m1_t x_vec = __riscv_vle32_v(x, vl);
    vfloat32m1_t a_row = __riscv_vle32_v(&A[i][0], vl);

    vfloat32m1_t prod = __riscv_vfmul_vv(a_row, x_vec, vl);
    prod = __riscv_vfmul_vf(prod, alpha, vl);
    vfloat32m1_t sum = __riscv_vfredosum_vs(prod, 0.0, vl);
    w[i] = w_val + sum;
#else
    for (j = 0; j < _PB_N; j++) {
      w_val = w_val + alpha * A[i][j] * x[j];
    }
    w[i] = w_val;
#endif
  }

#pragma endscop
}

