static
void kernel_heat_3d(int tsteps,
		      int n,
		      DATA_TYPE POLYBENCH_3D(A,N,N,N,n,n,n),
		      DATA_TYPE POLYBENCH_3D(B,N,N,N,n,n,n))
{
  int t, i, j, k;

#pragma scop
    for (t = 1; t <= TSTEPS; t++) {
        for (i = 1; i < _PB_N-1; i++) {
            for (j = 1; j < _PB_N-1; j++) {
#if defined(__riscv_vector)
                size_t k_start = 1;
                size_t k_end = _PB_N - 1;
                size_t k_len = k_end - k_start;

                if (k_len > 0) {
                    vfloat32m1_t v_0125 = __riscv_vfmv_v_f(0.125f, 1);
                    vfloat32m1_t v_2_0 = __riscv_vfmv_v_f(2.0f, 1);

                    for (size_t k = k_start; k < k_end; ) {
                        size_t vl = __riscv_vsetvl_e32m1(k_end - k);

                        // Load A[i][j][k]
                        vfloat32m1_t a_center = __riscv_vle32_v_f32m1(&A[i][j][k], vl);

                        // Load A[i+1][j][k]
                        vfloat32m1_t a_i1 = __riscv_vle32_v_f32m1(&A[i+1][j][k], vl);

                        // Load A[i-1][j][k]
                        vfloat32m1_t a_im1 = __riscv_vle32_v_f32m1(&A[i-1][j][k], vl);

                        // Load A[i][j+1][k]
                        vfloat32m1_t a_j1 = __riscv_vle32_v_f32m1(&A[i][j+1][k], vl);

                        // Load A[i][j-1][k]
                        vfloat32m1_t a_jm1 = __riscv_vle32_v_f32m1(&A[i][j-1][k], vl);

                        // Load A[i][j][k+1]
                        vfloat32m1_t a_k1 = __riscv_vle32_v_f32m1(&A[i][j][k+1], vl);

                        // Load A[i][j][k-1]
                        vfloat32m1_t a_km1 = __riscv_vle32_v_f32m1(&A[i][j][k-1], vl);

                        // Compute x-direction: (A[i+1][j][k] - 2.0*A[i][j][k] + A[i-1][j][k])
                        vfloat32m1_t term_x = __riscv_vfsub_vv(a_i1, __riscv_vfmul_vv(v_2_0, a_center, vl), vl);
                        term_x = __riscv_vfadd_vv(term_x, a_im1, vl);

                        // Compute y-direction: (A[i][j+1][k] - 2.0*A[i][j][k] + A[i][j-1][k])
                        vfloat32m1_t term_y = __riscv_vfsub_vv(a_j1, __riscv_vfmul_vv(v_2_0, a_center, vl), vl);
                        term_y = __riscv_vfadd_vv(term_y, a_jm1, vl);

                        // Compute z-direction: (A[i][j][k+1] - 2.0*A[i][j][k] + A[i][j][k-1])
                        vfloat32m1_t term_z = __riscv_vfsub_vv(a_k1, __riscv_vfmul_vv(v_2_0, a_center, vl), vl);
                        term_z = __riscv_vfadd_vv(term_z, a_km1, vl);

                        // Sum all terms
                        vfloat32m1_t sum_terms = __riscv_vfadd_vv(term_x, term_y, vl);
                        sum_terms = __riscv_vfadd_vv(sum_terms, term_z, vl);

                        // Multiply by 0.125
                        vfloat32m1_t scaled = __riscv_vfmul_vv(v_0125, sum_terms, vl);

                        // Add A[i][j][k]
                        vfloat32m1_t result = __riscv_vfadd_vv(scaled, a_center, vl);

                        // Store to B[i][j][k]
                        __riscv_vse32_v_f32m1(&B[i][j][k], result, vl);

                        k += vl;
                    }
                }
#else
                for (k = 1; k < _PB_N-1; k++) {
                    B[i][j][k] =   SCALAR_VAL(0.125) * (A[i+1][j][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i-1][j][k])
                                 + SCALAR_VAL(0.125) * (A[i][j+1][k] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j-1][k])
                                 + SCALAR_VAL(0.125) * (A[i][j][k+1] - SCALAR_VAL(2.0) * A[i][j][k] + A[i][j][k-1])
                                 + A[i][j][k];
                }
#endif
            }
        }
        for (i = 1; i < _PB_N-1; i++) {
           for (j = 1; j < _PB_N-1; j++) {
               for (k = 1; k < _PB_N-1; k++) {
                   A[i][j][k] =   SCALAR_VAL(0.125) * (B[i+1][j][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i-1][j][k])
                                + SCALAR_VAL(0.125) * (B[i][j+1][k] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j-1][k])
                                + SCALAR_VAL(0.125) * (B[i][j][k+1] - SCALAR_VAL(2.0) * B[i][j][k] + B[i][j][k-1])
                                + B[i][j][k];
               }
           }
       }
    }
#pragma endscop

}

