#include <riscv_vector.h>
#endif

static
void kernel_jacobi_1d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_1D(A,N,n),
			    DATA_TYPE POLYBENCH_1D(B,N,n))
{
  int t, i;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      // First update: B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1])
      #if defined(__riscv_vector)
      {
        size_t start = 1;
        size_t end = _PB_N - 1;
        size_t len = end - start;

        if (len > 0) {
          size_t vl = __riscv_vsetvlmax_e32m1();
          size_t i_vec = start;

          // Process vectorized portion
          while (i_vec + vl <= end) {
            vfloat32m1_t v_a_prev = __riscv_vle32_vf((float*)(A + i_vec - 1), vl);
            vfloat32m1_t v_a_curr = __riscv_vle32_vf((float*)(A + i_vec), vl);
            vfloat32m1_t v_a_next = __riscv_vle32_vf((float*)(A + i_vec + 1), vl);

            vfloat32m1_t v_sum = __riscv_vadd_vv(v_a_prev, v_a_curr, vl);
            v_sum = __riscv_vadd_vv(v_sum, v_a_next, vl);

            vfloat32m1_t v_const = __riscv_vfmv_v_f(0.33333f, vl);
            vfloat32m1_t v_result = __riscv_vfmul_vv(v_sum, v_const, vl);

            __riscv_vse32_vf((float*)(B + i_vec), v_result, vl);

            i_vec += vl;
          }

          // Handle remaining elements
          if (i_vec < end) {
            size_t rem = end - i_vec;
            size_t vl_rem = __riscv_vsetvl_e32m1(rem);

            vfloat32m1_t v_a_prev = __riscv_vle32_vf((float*)(A + i_vec - 1), vl_rem);
            vfloat32m1_t v_a_curr = __riscv_vle32_vf((float*)(A + i_vec), vl_rem);
            vfloat32m1_t v_a_next = __riscv_vle32_vf((float*)(A + i_vec + 1), vl_rem);

            vfloat32m1_t v_sum = __riscv_vadd_vv(v_a_prev, v_a_curr, vl_rem);
            v_sum = __riscv_vadd_vv(v_sum, v_a_next, vl_rem);

            vfloat32m1_t v_const = __riscv_vfmv_v_f(0.33333f, vl_rem);
            vfloat32m1_t v_result = __riscv_vfmul_vv(v_sum, v_const, vl_rem);

            __riscv_vse32_vf((float*)(B + i_vec), v_result, vl_rem);
          }
        }
      }
      #else
      for (i = 1; i < _PB_N - 1; i++)
        B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1]);
      #endif

      // Second update: A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1])
      #if defined(__riscv_vector)
      {
        size_t start = 1;
        size_t end = _PB_N - 1;
        size_t len = end - start;

        if (len > 0) {
          size_t vl = __riscv_vsetvlmax_e32m1();
          size_t i_vec = start;

          // Process vectorized portion
          while (i_vec + vl <= end) {
            vfloat32m1_t v_b_prev = __riscv_vle32_vf((float*)(B + i_vec - 1), vl);
            vfloat32m1_t v_b_curr = __riscv_vle32_vf((float*)(B + i_vec), vl);
            vfloat32m1_t v_b_next = __riscv_vle32_vf((float*)(B + i_vec + 1), vl);

            vfloat32m1_t v_sum = __riscv_vadd_vv(v_b_prev, v_b_curr, vl);
            v_sum = __riscv_vadd_vv(v_sum, v_b_next, vl);

            vfloat32m1_t v_const = __riscv_vfmv_v_f(0.33333f, vl);
            vfloat32m1_t v_result = __riscv_vfmul_vv(v_sum, v_const, vl);

            __riscv_vse32_vf((float*)(A + i_vec), v_result, vl);

            i_vec += vl;
          }

          // Handle remaining elements
          if (i_vec < end) {
            size_t rem = end - i_vec;
            size_t vl_rem = __riscv_vsetvl_e32m1(rem);

            vfloat32m1_t v_b_prev = __riscv_vle32_vf((float*)(B + i_vec - 1), vl_rem);
            vfloat32m1_t v_b_curr = __riscv_vle32_vf((float*)(B + i_vec), vl_rem);
            vfloat32m1_t v_b_next = __riscv_vle32_vf((float*)(B + i_vec + 1), vl_rem);

            vfloat32m1_t v_sum = __riscv_vadd_vv(v_b_prev, v_b_curr, vl_rem);
            v_sum = __riscv_vadd_vv(v_sum, v_b_next, vl_rem);

            vfloat32m1_t v_const = __riscv_vfmv_v_f(0.33333f, vl_rem);
            vfloat32m1_t v_result = __riscv_vfmul_vv(v_sum, v_const, vl_rem);

            __riscv_vse32_vf((float*)(A + i_vec), v_result, vl_rem);
          }
        }
      }
      #else
      for (i = 1; i < _PB_N - 1; i++)
        A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1]);
      #endif
    }
#pragma endscop

}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_jacobi_2d(int tsteps,
			    int n,
			    DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
			    DATA_TYPE POLYBENCH_2D(B,N,N,n,n))
{
  int t, i, j;

#pragma scop
  for (t = 0; t < _PB_TSTEPS; t++)
    {
      // First sweep: B = 0.2 * (A[i][j] + A[i][j-1] + A[i][j+1] + A[i+1][j] + A[i-1][j])
      for (i = 1; i < _PB_N - 1; i++)
	{
#if defined(__riscv_vector)
	  // Vectorized inner loop for j
	  int j_start = 1;
	  int j_end = _PB_N - 1;
	  vfloat32m1_t v02 = __riscv_vfmv_v_f_f32m1(0.2f, 1); // scalar 0.2 broadcasted

	  // Process vectorizable part
	  for (j = j_start; j + 4 <= j_end; j += 4)
	    {
	      // Load A[i][j-1]...A[i][j+2] (4 elements starting at j-1)
	      vfloat32m1_t v_center = __riscv_vle32_v_f32m1((const float*)&A[i][j-1], 4);
	      // Load A[i-1][j-1]...A[i-1][j+2]
	      vfloat32m1_t v_top = __riscv_vle32_v_f32m1((const float*)&A[i-1][j-1], 4);
	      // Load A[i+1][j-1]...A[i+1][j+2]
	      vfloat32m1_t v_bottom = __riscv_vle32_v_f32m1((const float*)&A[i+1][j-1], 4);

	      // For each element k in 0..3:
	      // result[k] = A[i][j+k] + A[i][j+k-1] + A[i][j+k+1] + A[i+1][j+k] + A[i-1][j+k]
	      // v_center[k] = A[i][j+k-1]
	      // We need A[i][j+k] which is v_center[k+1] (shifted left by 1)
	      // We need A[i][j+k+1] which is v_center[k+2] (shifted left by 2)

	      // Create shift vector (all 1s) for slideup
	      vuint32m1_t v_shift1 = __riscv_vmv_v_x_u32m1(1, 4);
	      vuint32m1_t v_shift2 = __riscv_vmv_v_x_u32m1(2, 4);

	      vfloat32m1_t v_center_shift1 = __riscv_vslideup_vv_f32m1(v_center, v_shift1, 4); // A[i][j]...A[i][j+3]
	      vfloat32m1_t v_center_shift2 = __riscv_vslideup_vv_f32m1(v_center, v_shift2, 4); // A[i][j+1]...A[i][j+4]

	      // Sum: v_center_shift1 (A[i][j+k]) + v_center (A[i][j+k-1]) + v_center_shift2 (A[i][j+k+1]) + v_bottom (A[i+1][j+k]) + v_top (A[i-1][j+k])
	      vfloat32m1_t v_sum = __riscv_vfadd_vv_f32m1(v_center_shift1, v_center, 4);
	      v_sum = __riscv_vfadd_vv_f32m1(v_sum, v_center_shift2, 4);
	      v_sum = __riscv_vfadd_vv_f32m1(v_sum, v_bottom, 4);
	      v_sum = __riscv_vfadd_vv_f32m1(v_sum, v_top, 4);

	      // Multiply by 0.2
	      vfloat32m1_t v_result = __riscv_vfmul_vv_f32m1(v_sum, v02, 4);

	      // Store to B[i][j]...B[i][j+3]
	      __riscv_vse32_v_f32m1((float*)&B[i][j], v_result, 4);
	    }
#else
	  for (j = 1; j < _PB_N - 1; j++)
	    B[i][j] = SCALAR_VAL(0.2) * (A[i][j] + A[i][j-1] + A[i][1+j] + A[1+i][j] + A[i-1][j]);
#endif
	}

      // Second sweep: A = 0.2 * (B[i][j] + B[i][j-1] + B[i][j+1] + B[i+1][j] + B[i-1][j])
      for (i = 1; i < _PB_N - 1; i++)
	{
#if defined(__riscv_vector)
	  int j_start = 1;
	  int j_end = _PB_N - 1;
	  vfloat32m1_t v02 = __riscv_vfmv_v_f_f32m1(0.2f, 1);
	  vuint32m1_t v_shift1 = __riscv_vmv_v_x_u32m1(1, 4);
	  vuint32m1_t v_shift2 = __riscv_vmv_v_x_u32m1(2, 4);

	  for (j = j_start; j + 4 <= j_end; j += 4)
	    {
	      vfloat32m1_t v_center = __riscv_vle32_v_f32m1((const float*)&B[i][j-1], 4);
	      vfloat32m1_t v_top = __riscv_vle32_v_f32m1((const float*)&B[i-1][j-1], 4);
	      vfloat32m1_t v_bottom = __riscv_vle32_v_f32m1((const float*)&B[i+1][j-1], 4);

	      vfloat32m1_t v_center_shift1 = __riscv_vslideup_vv_f32m1(v_center, v_shift1, 4);
	      vfloat32m1_t v_center_shift2 = __riscv_vslideup_vv_f32m1(v_center, v_shift2, 4);

	      vfloat32m1_t v_sum = __riscv_vfadd_vv_f32m1(v_center_shift1, v_center, 4);
	      v_sum = __riscv_vfadd_vv_f32m1(v_sum, v_center_shift2, 4);
	      v_sum = __riscv_vfadd_vv_f32m1(v_sum, v_bottom, 4);
	      v_sum = __riscv_vfadd_vv_f32m1(v_sum, v_top, 4);

	      vfloat32m1_t v_result = __riscv_vfmul_vv_f32m1(v_sum, v02, 4);

	      __riscv_vse32_v_f32m1((float*)&A[i][j], v_result, 4);
	    }
#else
	  for (j = 1; j < _PB_N - 1; j++)
	    A[i][j] = SCALAR_VAL(0.2) * (B[i][j] + B[i][j-1] + B[i][1+j] + B[1+i][j] + B[i-1][j]);
#endif
	}
    }
#pragma endscop

}

