#include <riscv_vector.h>
#endif

static
void kernel_ludcmp(int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;

  DATA_TYPE w;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    for (j = 0; j < i; j++) {
       w = A[i][j];
       for (k = 0; k < j; k++) {
          w -= A[i][k] * A[k][j];
       }
        A[i][j] = w / A[j][j];
    }
   for (j = i; j < _PB_N; j++) {
       w = A[i][j];
       for (k = 0; k < i; k++) {
          w -= A[i][k] * A[k][j];
       }
       A[i][j] = w;
    }
  }

  for (i = 0; i < _PB_N; i++) {
     w = b[i];
     for (j = 0; j < i; j++)
        w -= A[i][j] * y[j];
     y[i] = w;
  }

   for (i = _PB_N-1; i >=0; i--) {
     w = y[i];
     for (j = i+1; j < _PB_N; j++)
        w -= A[i][j] * x[j];
     x[i] = w / A[i][i];
  }
#pragma endscop

}

#if defined(__riscv_vector)
#include <riscv_vector.h>
#endif

static
void kernel_mvt(int n,
		DATA_TYPE POLYBENCH_1D(x1,N,n),
		DATA_TYPE POLYBENCH_1D(x2,N,n),
		DATA_TYPE POLYBENCH_1D(y_1,N,n),
		DATA_TYPE POLYBENCH_1D(y_2,N,n),
		DATA_TYPE POLYBENCH_2D(A,N,N,n,n))
{
  int i, j;

#pragma scop
  // First loop: x1[i] += A[i][j] * y_1[j]
  // This is a standard matrix-vector multiply where A is accessed row-wise.
  // We can vectorize the inner loop over j.
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc = 0.0;
    size_t vl;
    // Vectorize the inner loop
    for (j = 0; j < _PB_N; j += vl) {
      vl = __riscv_vsetvl_e64m1(_PB_N - j);
      vfloat64m1_t y_vec = __riscv_vle64_v_f64m1(&y_1[j], vl);
      vfloat64m1_t a_vec = __riscv_vle64_v_f64m1(&A[i][j], vl);
      vfloat64m1_t prod = __riscv_vfmul_vv_f64m1(a_vec, y_vec, vl);
      acc = __riscv_vfredosum_vs_f64m1_f64m1(prod, acc, vl);
    }
    x1[i] += acc;
  }

  // Second loop: x2[i] += A[j][i] * y_2[j]
  // This is equivalent to x2 = A^T * y_2.
  // A is accessed column-wise (A[j][i]), which is non-contiguous in memory.
  // We can still vectorize the inner loop over j, but we need to load A[j][i] carefully.
  // Since A[j][i] for fixed i and varying j is strided by N, we use stride load.
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE acc = 0.0;
    size_t vl;
    for (j = 0; j < _PB_N; j += vl) {
      vl = __riscv_vsetvl_e64m1(_PB_N - j);
      vfloat64m1_t y_vec = __riscv_vle64_v_f64m1(&y_2[j], vl);
      // Load A[j][i] with stride N (assuming DATA_TYPE is double, size 8 bytes)
      // The stride in elements is N.
      vfloat64m1_t a_vec = __riscv_vle64_v_f64m1_stride(&A[0][i], vl, N);
      vfloat64m1_t prod = __riscv_vfmul_vv_f64m1(a_vec, y_vec, vl);
      acc = __riscv_vfredosum_vs_f64m1_f64m1(prod, acc, vl);
    }
    x2[i] += acc;
  }
#pragma endscop

}

