static
void kernel_syr2k(int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

#pragma scop
  for (i = 0; i < _PB_N; i++) {
    // Scale C[i][0..i] by beta
    for (j = 0; j <= i; j++)
      C[i][j] *= beta;

    // Vectorized accumulation over k
    for (k = 0; k < _PB_M; k++) {
      // Determine vector length for j loop (0 to i)
      int limit = i + 1;

      // We will process in chunks
      int j_start = 0;
      while (j_start < limit) {
        size_t vl_actual = __riscv_vsetvl_e32m1(limit - j_start);

        // Create index vector for j: j_start, j_start+1, ..., j_start+vl-1
        // Use vid with mask to generate indices starting from 0, then add offset
        vuint32m1_t v_idx = __riscv_vid_v(vl_actual);
        vuint32m1_t v_idx_shifted = __riscv_vadd_vx(v_idx, j_start, vl_actual);

        // Load A[j][k] for j in range
        // A is [N][M], so A[j][k] is at offset j*M + k
        // Base pointer for column k: &A[0][k]
        // Offset for row j: j * M
        vuint32m1_t v_offset_A = __riscv_vmul_vx(v_idx_shifted, M, vl_actual);
        vfloat32m1_t v_A_col = __riscv_vle32_vf(&A[0][k], v_offset_A, vl_actual);

        // Similarly for B[j][k]
        vuint32m1_t v_offset_B = __riscv_vmul_vx(v_idx_shifted, M, vl_actual);
        vfloat32m1_t v_B_col = __riscv_vle32_vf(&B[0][k], v_offset_B, vl_actual);

        // Load A[i][k] and B[i][k] (scalars, since i is fixed in inner loop)
        DATA_TYPE A_ik = A[i][k];
        DATA_TYPE B_ik = B[i][k];

        // Compute term1 = A[j][k] * alpha * B[i][k]
        vfloat32m1_t v_term1 = __riscv_vfmul_vf(v_A_col, B_ik, vl_actual);
        v_term1 = __riscv_vfmul_vf(v_term1, alpha, vl_actual);

        // Compute term2 = B[j][k] * alpha * A[i][k]
        vfloat32m1_t v_term2 = __riscv_vfmul_vf(v_B_col, A_ik, vl_actual);
        v_term2 = __riscv_vfmul_vf(v_term2, alpha, vl_actual);

        // Sum terms
        vfloat32m1_t v_sum = __riscv_vfadd_vv(v_term1, v_term2, vl_actual);

        // Load current C[i][j] for j in range
        // C[i][j] is at C[i * N + j]
        // Base = &C[i][0], index = j
        vfloat32m1_t v_C = __riscv_vle32_vf(&C[i][0], v_idx_shifted, vl_actual);

        // Add sum to C
        vfloat32m1_t v_C_new = __riscv_vfadd_vv(v_C, v_sum, vl_actual);

        // Store back
        __riscv_vse32_vf(&C[i][0], v_C_new, v_idx_shifted, vl_actual);

        j_start += vl_actual;
      }
    }
  }
#pragma endscop

}

